    if (!allowNegative && finalNum < 0) {
      return "Negative amounts not allowed";
    }
    if (!allowZero && finalNum === 0) {
      return "Amount cannot be zero";
    }

    // Check decimal places
    const decimalMatch = cleaned.match(/\.(\d+)/);
